/*selectMasterCmClSalesLogisTaxCreationList*/
/* ICOMGRDT.PROCESS_TYPE = '2' TR 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , GR.GR_DATE AS GR_DATE , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , GR.PO_NO AS PO_NO , GR.GR_NO AS GR_NO , GR.GR_SEQ AS GR_SEQ , GR.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = GR.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN GR.LOGIS_CLOSE_DEPT IS NOT NULL THEN GR.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , GR.AGENT AS AGENT , GR.DESCRIPTION AS DESCRIPTION , GR.SPECIFICATION AS SPECIFICATION , SUBSTR(GR.GR_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , GR.NTS_SEND_FLAG AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'02', PODT.WAREHOUSE_CODE) AS LOGISTICS_RATE , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'03', PODT.WAREHOUSE_CODE) AS LOGIS_RATE_STATUS , GR.BUYER_ITEM_NO FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND GR.AGENT = CM.COM_CODE AND GR.AP_BILL_FLAG = 'Y' AND GR.AR_BILL_FLAG = 'Y' AND NVL(GR.LOGIS_BILL_FLAG,'N') = 'N' AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE IN ('2') AND POHD.DOC_TYPE <> 'X' AND GR.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND GR.BUYER = #{st_buyer_code}
AND GR.AGENT = #{st_agent_code}
AND (GR.PO_NO LIKE #{st_po_no} || '%' OR GR.GR_NO LIKE #{st_po_no} || '%')
AND GR.BUYER IN ( SELECT GR.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
UNION ALL
/* ICOMGRDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN GR.LOGIS_CLOSE_DEPT IS NOT NULL THEN GR.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , GR.GR_DATE AS GR_DATE , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , GR.PO_NO AS PO_NO , GR.GR_NO AS GR_NO , GR.GR_SEQ AS GR_SEQ , GR.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = GR.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN GR.LOGIS_CLOSE_DEPT IS NOT NULL THEN GR.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , PODT.WAREHOUSE_CODE AS AGENT , GR.DESCRIPTION AS DESCRIPTION , GR.SPECIFICATION AS SPECIFICATION , SUBSTR(GR.GR_DATE,1,6) , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , GR.NTS_SEND_FLAG AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'02', PODT.WAREHOUSE_CODE) AS LOGISTICS_RATE , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'03', PODT.WAREHOUSE_CODE) AS LOGIS_RATE_STATUS , GR.BUYER_ITEM_NO FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = CM.COM_CODE /* GR.AGENT = '물류센타코드' , PODT.WAREHOUSE_CODE = '실공급사코드' */ AND GR.AP_BILL_FLAG = 'Y' AND GR.AR_BILL_FLAG = 'Y' AND NVL(GR.LOGIS_BILL_FLAG,'N') = 'N' AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.WAREHOUSE_CODE NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND GR.BUYER = #{st_buyer_code}
AND PODT.WAREHOUSE_CODE = #{st_agent_code} /* PODT.WAREHOUSE_CODE = '실공급사코드' */
AND (GR.PO_NO LIKE #{st_po_no} || '%' OR GR.GR_NO LIKE #{st_po_no} || '%')
AND GR.BUYER IN ( SELECT GR.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
ORDER BY KEP_DEPT, GR_DATE , PO_NO , GR_NO , GR_SEQ

/*selectMasterCmClSalesLogisTaxCreationList_v2*/
/* ICOMIVDT.PROCESS_TYPE = '2' TR 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , IV.DELIVERY_DATE AS DELIVERY_DATE , ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS IV_AMT , IV.PO_NO AS PO_NO , IV.INV_NO AS INV_NO , IV.INV_SEQ AS INV_SEQ , IV.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = IV.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN IV.LOGIS_CLOSE_DEPT IS NOT NULL THEN IV.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , IV.AGENT AS AGENT , IV.DESCRIPTION AS DESCRIPTION , IV.SPECIFICATION AS SPECIFICATION , SUBSTR(IV.DELIVERY_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'02', PODT.WAREHOUSE_CODE) AS LOGISTICS_RATE , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'03', PODT.WAREHOUSE_CODE) AS LOGIS_RATE_STATUS , IV.BUYER_ITEM_NO FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND IV.AGENT = CM.COM_CODE AND IV.AP_BILL_FLAG = 'Y' AND NVL(IV.LOGIS_BILL_FLAG,'N') = 'N' AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '2' AND POHD.DOC_TYPE <> 'X' AND IV.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND IV.BUYER = #{st_buyer_code}
AND IV.AGENT = #{st_agent_code}
AND IV.PO_NO LIKE #{st_po_no}
AND IV.BUYER IN ( SELECT IV.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
UNION ALL
/* ICOMIVDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN IV.LOGIS_CLOSE_DEPT IS NOT NULL THEN IV.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , IV.DELIVERY_DATE AS DELIVERY_DATE , ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS IV_AMT , IV.PO_NO AS PO_NO , IV.INV_NO AS INV_NO , IV.INV_SEQ AS INV__SEQ , IV.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = IV.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN IV.LOGIS_CLOSE_DEPT IS NOT NULL THEN IV.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , PODT.WAREHOUSE_CODE AS AGENT , IV.DESCRIPTION AS DESCRIPTION , IV.SPECIFICATION AS SPECIFICATION , SUBSTR(IV.DELIVERY_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'02', PODT.WAREHOUSE_CODE) AS LOGISTICS_RATE , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'03', PODT.WAREHOUSE_CODE) AS LOGIS_RATE_STATUS , IV.BUYER_ITEM_NO FROM ICOMIVDT IV /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = CM.COM_CODE /* IV.AGENT = '물류센타코드' , PODT.WAREHOUSE_CODE = '실공급사코드' */ AND IV.AP_BILL_FLAG = 'Y' AND NVL(IV.LOGIS_BILL_FLAG,'N') = 'N' AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.WAREHOUSE_CODE NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND IV.BUYER = #{st_buyer_code}
AND PODT.WAREHOUSE_CODE = #{st_agent_code} /* PODT.WAREHOUSE_CODE = '실공급사코드' */
AND IV.PO_NO LIKE #{st_po_no}
AND IV.BUYER IN ( SELECT IV.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
ORDER BY KEP_DEPT, DELIVERY_DATE , PO_NO , INV_NO , INV_SEQ

mapper.update:
/*updateMasterCmClSalesLogisTaxCreation*/

		UPDATE 
		    ICOMGRDT GR
		SET    LOGIS_CLOSE_DEPT = LPAD(#{KEP_DEPT}, 3, 0)
		WHERE 1=1
		AND BUYER = #{BUYER}
		AND GR_NO = #{GR_NO}
		AND GR_SEQ = #{GR_SEQ}

/*updateMasterCmClSalesLogisTaxCreation_v2*/

		UPDATE 
		    ICOMIVDT IV
		SET    LOGIS_CLOSE_DEPT = LPAD(#{KEP_DEPT}, 3, 0)
		WHERE 1=1
		AND BUYER = #{BUYER}
		AND INV_NO = #{INV_NO}
		AND INV_SEQ = #{INV_SEQ}

/*insertMasterCmClSalesLogisTaxCreation_KEPTARDT*/
INSERT INTO KEPTARDT /* 외상매출_세금계산서 */ ( TAX_BILL_NO , KEP_IRS , SITE , DEPT_CODE , STATUS , ISSUE_DATE , CUSTOMER_NAME , IRS_NO , BUYER_CODE
, TOT_SUPP_PRICE , TOT_TAX_PRICE , TOT_AMT , SUPP_PRICE , TAX_PRICE , AMT
, TAX_TYPE , BILL_TYPE , PRINT_DATE , PRINT_USER_ID , PRINT_CNT , PRINT_AVAIL_CNT , CONFIRM_FLAG , REMARK_DESCRIPTION , REMARK_SPECIFICATION , REMARK_QTY , REMARK_PRICE
, ASK_TYPE , ADD_DATE , ADD_TIME , ADD_USER_ID , CHANGE_DATE , CHANGE_TIME , CHANGE_USER_ID
, AR_CLOSE_MONTH , AR_CLOSE_REVISION , KEP_IRS_NAME , KEP_CEO_NAME_LOC , KEP_INDUSTRY_TYPE , KEP_BUSINESS_ITEMS , KEP_ADDRESS_LOC , IRS_NAME , CEO_NAME_LOC , INDUSTRY_TYPE , BUSINESS_ITEMS , ADDRESS_LOC , AR_TYPE , AGENT_CODE ) VALUES ( #{order_no} , #{KEP_IRS_NO} , DECODE(#{BUYER}, 'KRKOLO0077', 'KK','KA') , #{dept_code} , 'C' , #{issue_date} || #{issue_last_day} , #{agent_name} , #{agent_irs_no} , ' '
, TRUNC(#{tot_supp_price}) , TRUNC(#{tot_tax_price}) , TRUNC(#{tot_supp_price}+#{tot_tax_price}) , TRUNC(#{supp_price}) , TRUNC(#{supp_price}*0.1) , TRUNC(#{supp_price}+TRUNC(#{supp_price}*0.1))
, '11' /*TAX_TYPE*/ , (SELECT CM.BILL_TYPE FROM ICOMCMPY CM WHERE CM.COM_CODE = #{agent_code}) /*BILL_TYPE*/ , '' /*PRINT_DATE*/ , '' /*PRINT_USER_ID*/ , 0 /*PRINT_CNT*/ , 1 /*PRINT_AVAIL_CNT*/ , 'N' /*CONFIRM_FLAG*/ , SUBSTR(#{item_desc},0,25) , SUBSTR(#{item_desc},0,25) , 1 , #{tot_supp_price}
, '02' /*ASK_TYPE*/ , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id} , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id}
, #{issue_date} , #{st_close_revision} , (SELECT IRS_NAME FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_IRS_NAME */ , (SELECT CEO_NAME_LOC FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_CEO_NAME_LOC */ , (SELECT INDUSTRY_TYPE FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_INDUSTRY_TYPE */ , (SELECT BUSINESS_ITEMS FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_BUSINESS_ITEMS */ , (SELECT ADDRESS_LOC FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_ADDRESS_LOC */ , (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* IRS_NAME */ , (SELECT CEO_NAME_LOC FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* CEO_NAME_LOC */ , (SELECT INDUSTRY_TYPE FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* INDUSTRY_TYPE */ , (SELECT BUSINESS_ITEMS FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* BUSINESS_ITEMS */ , (SELECT ADDRESS_LOC FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* ADDRESS_LOC */ , '02' ,#{agent_code} )

/*updateMasterCmClSalesLogisTaxCreation_ICOMGRDT*/

		UPDATE 
		    ICOMGRDT /* 구매사별 입고정보 */
		SET
		    LOGIS_TAX_BILL_NO      = #{order_no}
		  , LOGIS_CLOSE_DEPT       = LPAD(#{dept_code},3,0)
		  , LOGIS_COLSE_MONTH      = #{issue_date}
		  ,  LOGIS_CLOSE_REVISION   = #{st_close_revision}
		  , LOGIS_BILL_FLAG        = 'Y'
		  , LOGIS_RATE= #{logistics_rate}
		  , LOGIS_AMT = #{logistics_amt}
		  , LOGIS_RATE_STATUS = #{logistics_rate_status}
		WHERE 1=1
		AND BUYER  = #{key_buyer}
		AND GR_NO  = #{key_gr_no}
		AND GR_SEQ = #{key_gr_seq}

/*updateMasterCmClSalesLogisTaxCreation_ICOMIVDT_v2*/

		UPDATE 
		    ICOMIVDT /* 구매사별 납품정보 */
		SET
		    LOGIS_TAX_BILL_NO      = #{order_no}
		  , LOGIS_CLOSE_DEPT       = LPAD(#{dept_code},3,0)
		  , LOGIS_COLSE_MONTH      = #{issue_date}
		  ,  LOGIS_CLOSE_REVISION   = #{st_close_revision}
		  , LOGIS_BILL_FLAG        = 'Y'
		  , LOGIS_RATE= #{logistics_rate}
		  , LOGIS_AMT = #{logistics_amt}
		  , LOGIS_RATE_STATUS = #{logistics_rate_status}
		WHERE 1=1
		AND BUYER  = #{key_buyer}
		AND INV_NO  = #{key_inv_no}
		AND INV_SEQ = #{key_inv_seq}
